import express, { Express, Request, Response ,NextFunction} from "express";
import dotenv from "dotenv";
import morgan from "morgan";
import compression from "compression";
import cors from "cors";
import SwaggerUi from "swagger-ui-express";
import Document from "../swagger.json";
import router from "./routes";
import httpStatus from "http-status";
import chat from "./services/chat";
import { createServer } from "http";
import { Server } from "socket.io";
import "./services/cronJob"

dotenv.config();

const app: Express = express();
const PORT = process.env.PORT
const server = createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});
chat(io);
app.use((req: Request, res: Response, next: NextFunction) => {
  if (req.originalUrl === "/api/cart/webhook") {
    express.raw({ type: "application/json" })(req, res, next);
  } else {
    express.json()(req, res, next);
  }
});
app.use(morgan(process.env.NODE_EN));
app.use(compression());
app.use(cors());

app.use("/api-docs", SwaggerUi.serve, SwaggerUi.setup(Document));
app.use("/api", router);

app.get("**", (req: Request, res: Response) => {
  res.status(httpStatus.OK).json({
    status: true,
    message: "Welcome to the e-Commerce Ninjas BackEnd."
  });
});


server.listen(PORT, () => {
  console.log(`Server is running on the port ${PORT}`);
});

export default app;

import { Router } from "express";
import authRouter from "./authRouter";
import userRouter from "./userRouter";
import productRouter from "./productRouter";
import cartRouter from "./cartRouter";
const router: Router = Router();

router.use("/auth", authRouter);
router.use("/user", userRouter);
router.use("/shop", productRouter);
router.use("/cart", cartRouter);

export default router;

import { Router } from "express";
import authControllers from "../modules/auth/controller/authControllers";
import {
  validation,
  isUserExist,
  isAccountVerified,
  isUserEnabled,
  verifyUser,
  isSessionExist,
  isGoogleEnabled,
  isUserVerified,
  verifyOtp,
  verifyUserCredentials 
} from "../middlewares/validation";
import {
  emailSchema,
  credentialSchema,
  otpSchema,
  is2FAenabledSchema,
  resetPasswordSchema 
} from "../modules/auth/validation/authValidations";
import { userAuthorization } from "../middlewares/authorization";
import googleAuth from "../services/googleAuth";
import { checkPasswordExpiration } from "../middlewares/passwordExpiryCheck";

const router: Router = Router();

router.post("/register",validation(credentialSchema),isUserExist,authControllers.registerUser
);
router.get(
  "/verify-email/:token",
  isAccountVerified,
  authControllers.verifyEmail
);
router.post(
  "/send-verify-email",
  validation(emailSchema),
  isAccountVerified,
  authControllers.sendVerifyEmail
);
router.post(
  "/login",
  validation(credentialSchema),
  isUserVerified,
  isUserEnabled,
  isGoogleEnabled,
  verifyUserCredentials, checkPasswordExpiration,
  authControllers.loginUser
);

router.post(
  "/logout",
  userAuthorization(["admin", "buyer", "seller"]),
  authControllers.logoutUser
);

router.get("/google", googleAuth.googleVerify);
router.get("/google/callback", googleAuth.authenticateWithGoogle);

router.post(
  "/verify-otp/:id",
  validation(otpSchema),
  verifyOtp,
  authControllers.loginUser
);
router.put(
  "/enable-2f",
  validation(is2FAenabledSchema),
  userAuthorization(["admin", "buyer", "seller"]),
  authControllers.updateUser2FA
);
router.post("/forget-password", validation(emailSchema), verifyUser, authControllers.forgetPassword);
router.put("/reset-password/:token", validation(resetPasswordSchema), verifyUser, isSessionExist, authControllers.resetPassword);

export default router;

/* eslint-disable @typescript-eslint/no-explicit-any */
import { Request, Response } from "express";
import userRepositories from "../repository/authRepositories";
import { generateToken} from "../../../helpers";
import httpStatus from "http-status";
import { usersAttributes } from "../../../databases/models/users";
import authRepositories from "../repository/authRepositories";
import { sendEmail } from "../../../services/sendEmail";

const registerUser = async (req: Request, res: Response): Promise<void> => {
  try {
    const register: usersAttributes = await authRepositories.createUser(
      req.body
    );
    const token: string = generateToken(register.id);
    const session = {
      userId: register.id,
      device: req.headers["user-device"],
      token: token,
      otp: null
    };
    await authRepositories.createSession(session);
    await sendEmail(
      register.email,
      "Verification Email",
      `${process.env.SERVER_URL_PRO}/api/auth/verify-email/${token}`
    );
    res.status(httpStatus.CREATED).json({
      message:
        "Account created successfully. Please check email to verify account.",
      data: { user: register }
    });
  } catch (error) {
    res.status(httpStatus.INTERNAL_SERVER_ERROR).json({
      status: httpStatus.INTERNAL_SERVER_ERROR,
      message: error.message
    });
  }
};

const sendVerifyEmail = async (req: any, res: Response) => {
  try {
    await sendEmail(
      req.user.email,
      "Verification Email",
      `${process.env.SERVER_URL_PRO}/api/auth/verify-email/${req.session.token}`
    );
    res.status(httpStatus.OK).json({
      status: httpStatus.OK,
      message: "Verification email sent successfully."
    });
  } catch (error) {
    return res.status(httpStatus.INTERNAL_SERVER_ERROR).json({
      status: httpStatus.INTERNAL_SERVER_ERROR,
      message: error.message
    });
  }
};

const verifyEmail = async (req: any, res: Response) => {
  try {
    await authRepositories.destroySessionByAttribute(
      "userId",
      req.user.id,
      "token",
      req.session.token
    );
    await authRepositories.updateUserByAttributes("isVerified", true, "id", req.user.id);
    res.status(httpStatus.OK).json({ status: httpStatus.OK, message: "Account verified successfully, now login." });
  } catch (error) {
    return res.status(httpStatus.INTERNAL_SERVER_ERROR).json({ status: httpStatus.INTERNAL_SERVER_ERROR, message: error.message });
  }
}

const loginUser = async (req: any, res: Response) => {
  try {
    const token = generateToken(req.user.id);
    const session = {
      userId: req.user.id,
      device: req.headers["user-device"],
      token: token,
      otp: null
    };
    await userRepositories.createSession(session);
    res
      .status(httpStatus.OK)
      .json({ message: "Logged in successfully", data: { token } });
  } catch (err) {
    return res
      .status(httpStatus.INTERNAL_SERVER_ERROR)
      .json({ message: "Internal Server error", data: err.message });
  }
};

const logoutUser = async (req: any, res: Response) => {
  try {
    await authRepositories.destroySessionByAttribute(
      "userId",
      req.user.id,
      "token",
      req.session.token
    );
    res.status(httpStatus.OK).json({ message: "Successfully logged out" });
  } catch (err) {
    return res
      .status(httpStatus.INTERNAL_SERVER_ERROR)
      .json({
        status: httpStatus.INTERNAL_SERVER_ERROR,
        message: "Internal Server error"
      });
  }
};
const forgetPassword = async (req: any, res: Response): Promise<void> => {
  try {
      const token = generateToken(req.user.id);
      const session = {
        userId: req.user.id,
        device: req.headers["user-device"],
        token: token,
        otp: null
      };
      await authRepositories.createSession(session);
      await sendEmail(req.user.email, "Reset password", `${process.env.SERVER_URL_PRO}/api/auth/reset-password/${token}`);
      res.status(httpStatus.OK).json({ status: httpStatus.OK, message: "Check email for reset password."});
  } catch (error) {
      res.status(httpStatus.INTERNAL_SERVER_ERROR).json({ message: error.message });
  }
}

const resetPassword = async (req: any, res: Response): Promise<void> => {
  try {
    await authRepositories.updateUserByAttributes("password", req.user.password, "id", req.user.id);  
      res.status(httpStatus.OK).json({status: httpStatus.OK, message: "Password reset successfully." });
  } catch (error) {
      res.status(httpStatus.INTERNAL_SERVER_ERROR).json({ message: error.message });
  }
};

const updateUser2FA = async (req: any, res: Response) => {
  try {
    const user = await authRepositories.updateUserByAttributes(
      "is2FAEnabled",
      true,
      "id",
      req.user.id
    );
    res.status(httpStatus.OK).json({
      status: httpStatus.OK,
      message: "2FA enabled successfully.",
      data: { user: user }
    });
  } catch (error) {
    return res.status(httpStatus.INTERNAL_SERVER_ERROR).json({
      status: httpStatus.INTERNAL_SERVER_ERROR,
      message: error.message
    });
  }
};
export default {
  registerUser,
  sendVerifyEmail,
  verifyEmail,
  loginUser,
  forgetPassword,
  resetPassword,
  logoutUser,
  updateUser2FA
};

