import jwt,{JwtPayload} from "jsonwebtoken"
import dotenv from "dotenv"
import bcrypt from "bcrypt"

dotenv.config

 const generateToken = (id: string) => {
    return jwt.sign({ id }, process.env.JWT_SECRET);
  };

  const decodeToken = (token: string) => {
    return jwt.verify(token, process.env.JWT_SECRET) as JwtPayload
    ;
  };

  const comparePassword = async (password: string, hashedPassword: string) =>{
    return await bcrypt.compare(password, hashedPassword);
}

const hashPassword = (password: string)=>{
  return bcrypt.hashSync(password, 10);
}

const generateRandomCode = (): string => {
  return Math.floor(100000 + Math.random() * 900000).toString();
};

const generateOTP = () => {
  const otp = generateRandomCode();
  const expirationTime = new Date(Date.now() + 5 * 60 * 1000);
  return { otp, expirationTime };
};

  export { generateToken, decodeToken, comparePassword, hashPassword, generateRandomCode,generateOTP }

/* eslint-disable @typescript-eslint/no-unused-vars */
import { Request, Response } from "express";
import nodemailer, { SendMailOptions } from "nodemailer";
import dotenv from "dotenv";

dotenv.config();
const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST,
  port: Number(process.env.SMTP_HOST_PORT),
  secure: true,
  auth: {
    user: process.env.MAIL_ID,
    pass: process.env.MP
  }
});

const sendEmail = async(email: string, subject: string, message: string) => {
    try {
        const mailOptionsVerify: SendMailOptions = {
            from: process.env.MAIL_ID,
            to: email,
            subject: subject,
            text: message
        };
    
        await transporter.sendMail(mailOptionsVerify);
    } catch (error) {
        throw new Error(error);
    }
};


export {  sendEmail, transporter };

